def eval_rpn(tokens: list[str]) -> int:
    """
    Evaluate a Reverse Polish Notation expression consisting of integer tokens
    and the binary operators +, -, *, and /.

    Division truncates toward zero.
    """
    stack: list[int] = []

    def truncate_divide(a: int, b: int) -> int:
        if b == 0:
            raise ZeroDivisionError("division by zero")
        quotient = abs(a) // abs(b)
        if (a < 0) ^ (b < 0):
            return -quotient
        return quotient

    for token in tokens:
        if token == "+":
            if len(stack) < 2:
                raise ValueError("invalid RPN expression")
            b = stack.pop()
            a = stack.pop()
            stack.append(a + b)
        elif token == "-":
            if len(stack) < 2:
                raise ValueError("invalid RPN expression")
            b = stack.pop()
            a = stack.pop()
            stack.append(a - b)
        elif token == "*":
            if len(stack) < 2:
                raise ValueError("invalid RPN expression")
            b = stack.pop()
            a = stack.pop()
            stack.append(a * b)
        elif token == "/":
            if len(stack) < 2:
                raise ValueError("invalid RPN expression")
            b = stack.pop()
            a = stack.pop()
            stack.append(truncate_divide(a, b))
        else:
            stack.append(int(token))

    if len(stack) != 1:
        raise ValueError("invalid RPN expression")

    return stack[0]
