def decode_string(s: str) -> str:
    stack = []
    current = []
    num = 0

    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == '[':
            stack.append((current, num))
            current = []
            num = 0
        elif ch == ']':
            prev, repeat = stack.pop()
            current = prev + current * repeat
        else:
            current.append(ch)

    return ''.join(current)
