def next_permutation(nums: list[int]) -> list[int]:
    arr = nums.copy()
    n = len(arr)

    i = n - 2
    while i >= 0 and arr[i] >= arr[i + 1]:
        i -= 1

    if i < 0:
        return sorted(arr)

    j = n - 1
    while arr[j] <= arr[i]:
        j -= 1

    arr[i], arr[j] = arr[j], arr[i]
    arr[i + 1:] = arr[i + 1:][::-1]

    return arr
