def count_islands(grid: list[list[str]]) -> int:
    if not grid:
        return 0

    rows = len(grid)
    visited = set()
    count = 0

    for r, row in enumerate(grid):
        for c, cell in enumerate(row):
            if cell == "1" and (r, c) not in visited:
                count += 1
                stack = [(r, c)]
                visited.add((r, c))

                while stack:
                    i, j = stack.pop()

                    for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ni, nj = i + di, j + dj

                        if (
                            0 <= ni < rows
                            and 0 <= nj < len(grid[ni])
                            and (ni, nj) not in visited
                            and grid[ni][nj] == "1"
                        ):
                            visited.add((ni, nj))
                            stack.append((ni, nj))

    return count
