def word_break(s: str, words: list[str]) -> bool:
    word_set = {w for w in words if w}
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True

    max_len = max(map(len, word_set), default=0)

    for i in range(1, n + 1):
        for j in range(max(0, i - max_len), i):
            if dp[j] and s[j:i] in word_set:
                dp[i] = True
                break

    return dp[n]
```

